CREATE TABLE students (id UUID PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, verified BOOLEAN NOT NULL DEFAULT FALSE, bio VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE email_tokens (id UUID PRIMARY KEY, student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE, token_hash CHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, used_at TIMESTAMPTZ);
CREATE INDEX idx_email_tokens_student ON email_tokens(student_id);
CREATE TABLE refresh_tokens (id UUID PRIMARY KEY, student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE, token_hash CHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ);
CREATE INDEX idx_refresh_student ON refresh_tokens(student_id);
CREATE TABLE skills (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE student_skills (student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE, skill_id BIGINT NOT NULL REFERENCES skills(id), proficiency VARCHAR(20) NOT NULL CHECK (proficiency IN ('BEGINNER','INTERMEDIATE','ADVANCED')), PRIMARY KEY(student_id,skill_id));
CREATE TABLE subjects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE student_subjects (student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE, subject_id BIGINT NOT NULL REFERENCES subjects(id), proficiency VARCHAR(20) NOT NULL CHECK (proficiency IN ('BEGINNER','INTERMEDIATE','ADVANCED')), PRIMARY KEY(student_id,subject_id));
CREATE TABLE campus_zones (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, enabled BOOLEAN NOT NULL DEFAULT TRUE);
INSERT INTO campus_zones(name) VALUES ('Library'),('Computer Lab'),('Cafeteria'),('Study Hall');
CREATE TABLE presence (student_id UUID PRIMARY KEY REFERENCES students(id) ON DELETE CASCADE, zone_id BIGINT NOT NULL REFERENCES campus_zones(id), status VARCHAR(20) NOT NULL CHECK (status IN ('AVAILABLE','BUSY')), expires_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_presence_active ON presence(expires_at,zone_id,status);
